from pwn import *

def read_encrypted_passwords():
    """Read and parse encrypted_passwords.txt"""
    with open('encrypted_passwords.txt', 'rb') as f:
        # Split on newlines and filter out empty lines
        return [line.strip(b'\n') for line in f.readlines() if line.strip()]

def decrypt_password(encrypted, key):
    """Decrypt a password using recovered key"""
    decrypted = b''.join((x ^ y).to_bytes(1,'big') for (x,y) in zip(encrypted, key))
    try:
        return decrypted.decode('ascii')
    except:
        return None

def is_valid_password(password):
    """Check if password matches Pokemon-Type-Type pattern"""
    if not password:
        return False
    parts = password.split('-')
    return len(parts) == 3 and all(x.isalpha() for x in parts[1:])

def recover_key(known_plain, encrypted):
    """Recover encryption key using known plaintext-ciphertext pair"""
    plain_bytes = known_plain.encode()
    return bytes(p ^ c for p, c in zip(plain_bytes, encrypted))

def main():
    # Read the leaked password
    with open('leaked_password.txt', 'r') as f:
        known_plain = f.read().strip()

    # Read all encrypted passwords
    encrypted_passwords = read_encrypted_passwords()

    # Find the encrypted form of the known password
    key = None
    found_key = False
    for enc_pass in encrypted_passwords:
        if len(enc_pass) == len(known_plain.encode()):
            test_key = recover_key(known_plain, enc_pass)
            # Try the key on the known password first
            if decrypt_password(enc_pass, test_key) == known_plain:
                key = test_key
                found_key = True
                print(f"[+] Found key using known plaintext!")
                break

    if not found_key:
        print("[-] Failed to find encryption key!")
        return

    print("\n[+] Decrypted passwords:")
    print("-" * 40)

    admin_candidates = []
    for encrypted in encrypted_passwords:
        if len(encrypted) > len(key):
            continue

        decrypted = decrypt_password(encrypted, key)
        if decrypted and is_valid_password(decrypted):
            print(f"Found valid password: {decrypted}")
            admin_candidates.append(decrypted)

    print("\n[+] Potential admin passwords:")
    for password in admin_candidates:
        print(password)

if __name__ == '__main__':
    main()

